CREATE TABLE IF NOT EXISTS pv_quota(bucket TEXT PRIMARY KEY,n INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pv_client(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,source TEXT NOT NULL,synthetic INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pv_event(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,client_id TEXT,stage TEXT NOT NULL,source TEXT NOT NULL,synthetic INTEGER NOT NULL,valid INTEGER,elapsed_ms REAL,at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS pv_event_client ON pv_event(client_id,at);
